const schemaDriftRepaired=new WeakSet<object>();
const schedulingTablesReady=new WeakSet<object>();
const schedulingTablesPending=new WeakMap<object,Promise<void>>();
async function ensureSchedulingTables(db:Awaited<ReturnType<typeof database>>){
 if(schedulingTablesReady.has(db))return;
 const running=schedulingTablesPending.get(db);if(running)return running;
 const pending=initializeSchedulingTables(db).then(()=>{schedulingTablesReady.add(db);}).finally(()=>{schedulingTablesPending.delete(db);});
