async function initializeSchedulingTables(db:Awaited<ReturnType<typeof database>>){
  /*
   * provider_unavailability is owned by lib/provider-capacity-governance.ts, and the read-fanout
   * collapse below both indexes and queries it. Indexing or selecting a table this route never
   * created fails with "no such table: main.provider_unavailability" on any database where the
   * capacity module has not run first - which is every scheduling test that seeds only its own
   * tables, and any cold environment where a scheduling request arrives before a capacity one.
   * ensureProviderCapacityTables carries a per-isolate WeakSet guard, so this is a no-op after the
   * first call and costs the fanout improvement nothing.
   */
  await ensureProviderCapacityTables(db);
  await db.batch([
  db.prepare("CREATE TABLE IF NOT EXISTS scheduling_assignment_decisions (group_id TEXT PRIMARY KEY,strategy TEXT NOT NULL,shortlist_json TEXT NOT NULL,selected_provider_id TEXT,status TEXT NOT NULL,actor_id TEXT,reason TEXT,updated_at INTEGER NOT NULL)"),
  db.prepare("CREATE TABLE IF NOT EXISTS scheduling_rules (id TEXT PRIMARY KEY,name TEXT NOT NULL,service_code TEXT,city_id TEXT,zone_id TEXT,priority INTEGER NOT NULL DEFAULT 100,condition_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)"),
  db.prepare("CREATE TABLE IF NOT EXISTS scheduling_availability (id TEXT PRIMARY KEY,provider_id TEXT NOT NULL,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,date TEXT NOT NULL,windows_json TEXT NOT NULL,source TEXT NOT NULL,updated_at INTEGER NOT NULL)"),
  db.prepare("CREATE TABLE IF NOT EXISTS scheduling_reservations (id TEXT PRIMARY KEY,group_id TEXT NOT NULL,provider_id TEXT NOT NULL,service_code TEXT NOT NULL,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,customer_id TEXT NOT NULL,pet_ids_json TEXT NOT NULL,scheduled_start TEXT NOT NULL,scheduled_end TEXT NOT NULL,capacity_units INTEGER NOT NULL DEFAULT 1,occurrence_number INTEGER NOT NULL DEFAULT 1,care_mode TEXT,status TEXT NOT NULL,explanation_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,lease_expires_at INTEGER,customer_session_id TEXT,attempt_id TEXT)"),
  db.prepare("CREATE TABLE IF NOT EXISTS scheduling_dispatch_assertions (id TEXT PRIMARY KEY,ok INTEGER NOT NULL CHECK(ok=1),created_at INTEGER NOT NULL)"),
  db.prepare("CREATE INDEX IF NOT EXISTS idx_scheduling_availability_provider_date ON scheduling_availability(provider_id,date)"),
  db.prepare("CREATE INDEX IF NOT EXISTS idx_scheduling_availability_date_provider_source ON scheduling_availability(date,provider_id,source)"),
  db.prepare("CREATE INDEX IF NOT EXISTS idx_scheduling_reservations_provider ON scheduling_reservations(city_id,provider_id,status)"),
  db.prepare("CREATE INDEX IF NOT EXISTS idx_scheduling_reservations_city_status_provider_window ON scheduling_reservations(city_id,status,provider_id,scheduled_start,scheduled_end)"),
  db.prepare("CREATE INDEX IF NOT EXISTS idx_scheduling_reservations_group ON scheduling_reservations(group_id)"),
]);
  /*
   * attempt_id must exist as a COLUMN before anything names it, and a CREATE TABLE IF NOT EXISTS
   * above cannot put it there: scheduling_reservations is declared in more than one module, so on
   * any database where the table already exists the declaration is a no-op and the real shape is
   * whatever the first writer chose. Every live database is in exactly that state - the table
   * predates attempt_id - so indexing or inserting the column raised
   *
   *   D1_ERROR: no such column: attempt_id at offset 90: SQLITE_ERROR
   *
   * from ensureSchedulingTables, i.e. a 500 on EVERY scheduling request, not a degraded one. The
   * runtime-D1 regression harness caught it because it is the only suite that runs against real D1
   * with the table already created; the node:sqlite suites each build the table from this route's
   * own declaration and so never see the drifted shape.
   *
   * repairSchemaDrift is the codebase's mechanism for this and already registers the column. It
   * only ever ADDs genuinely-absent columns to tables that already exist, so it is a no-op on a
   * cold database that just got the full declaration above. The per-isolate guard keeps it off the
   * hot path after the first call - this is the booking write path - and records only success, so a
   * failed repair is retried rather than latched.
   */
  if(!schemaDriftRepaired.has(db)){await repairSchemaDrift(db);schemaDriftRepaired.add(db);}
  await db.batch([
  db.prepare("CREATE INDEX IF NOT EXISTS idx_scheduling_reservations_attempt ON scheduling_reservations(attempt_id)"),
]);await ensureSchedulingReservationLeaseGovernance(db);}

/** What the UAT roster seeder publishes for this request (dates, window, zone). Null unless seeding is declared. */
