async function authoredRosterKeys(db:Awaited<ReturnType<typeof database>>,dates:string[]){const sorted=[...dates].sort(),authoredRows=await db.prepare("SELECT provider_id,date FROM scheduling_availability WHERE date>=? AND date<=? AND source IN ('partner_app','operations','roster')").bind(sorted[0]??"",sorted[sorted.length-1]??"").all<Record<string,unknown>>();return new Set(authoredRows.results.map(row=>`${String(row.provider_id)}|${String(row.date)}`));}
const uatRosterRow=(seed:NonNullable<Awaited<ReturnType<typeof uatRosterSeed>>>,providerId:string,date:string)=>({id:`uat_${providerId}_${date}_${seed.zoneId}`,provider_id:providerId,city_id:seed.cityId,zone_id:seed.zoneId,date,windows_json:JSON.stringify([seed.window]),source:seed.source,updated_at:Date.now()});
/** Live, in-city profiles offering this service in this zone on the appointment date: the seeder's set, and a superset of the governed candidates. */
async function matchingProfiles(db:Awaited<ReturnType<typeof database>>,input:RequestBody){const scheduledDate=new Date(input.scheduledStart).toISOString().slice(0,10),zoneId=zoneIdFor(input),profileRows=await db.prepare("SELECT * FROM provider_capacity_profiles WHERE city_id=? AND live=1 AND status='active' AND effective_from<=? AND (effective_to IS NULL OR effective_to>=?)").bind(cityIdFor(input),scheduledDate,scheduledDate).all<Record<string,unknown>>();return profileRows.results.filter(row=>{try{return (JSON.parse(String(row.services_json||"[]")) as string[]).includes(input.serviceCode)&&(JSON.parse(String(row.zones_json||"[]")) as string[]).includes(zoneId);}catch{return false;}}).map(row=>({id:String(row.id),travelBufferMinutes:Number(row.travel_buffer_minutes)}));}
type UatRosterReads={matching:ReturnType<typeof matchingProfiles>;authored:ReturnType<typeof authoredRosterKeys>};
/** The two reads seedUatRoster and uatRosterPlan both make, started once and shared by the reserve path. Null unless seeding is declared. */
