/*
 * Staging testers share one small UAT roster. Appointment scheduling holds one job per provider per
 * buffer-widened window, so every Training test booking removed its trainer from that window for good and
 * an 8+ session programme soon matched nobody ("No available trainer has been confirmed in <zone> for this
 * programme"). On a DECLARED UAT runtime only - the same explicit PAWSPACE_SCHEDULING_ENV=uat that
 * seedUatRoster needs, which production never declares - a Training provider may hold buffer-overlapping
 * sessions up to its seeded capacity (backend/src/scheduling.ts parallelAppointments). Capacity-1 trainers
 * and every other service keep the one-at-a-time rule. Preview, reserve, Ops assignment, the commit guard
 * and the reassign restore all read this one answer, so they cannot disagree.
 */
export async function parallelAppointmentsFor(input:Pick<RequestBody,"serviceCode">){if(input.serviceCode!=="dog_training")return false;const {env}=await import("cloudflare:workers");return uatRosterSeedingEnabled(env);}

type PreviewTrace={zone:string|null;providers:number|null;mark(name:string):void};
type RepositoryOptions={eager?:boolean;rosterInMemory?:boolean;trace?:PreviewTrace|null;/** Roster reads the caller already started (reserve); read again when absent. */rosterReads?:UatRosterReads|null};
const BOOKING_READ_COLUMNS="id,group_id,provider_id,service_code,city_id,zone_id,customer_id,pet_ids_json,scheduled_start,scheduled_end,capacity_units,occurrence_number,care_mode,status,created_at";
/**
 * The reservations evaluateProvider can see, and no others: this city's non-cancelled rows for the
 * candidate providers that overlap the request window widened by the largest travel buffer (never less
 * than a day), which also covers every booking on the same local day for the daily-job cap. It used to be
 * every non-cancelled reservation in the city for all time, SELECT *. Rows whose times SQLite cannot parse
 * are kept so the evaluator, not the query, decides about them.
 */
function boundedBookingRows(db:Awaited<ReturnType<typeof database>>,cityId:string,providers:Array<{id:string;travelBufferMinutes?:number}>,occurrences:Array<{start:string;end:string}>){const ids=[...new Set(providers.map(provider=>provider.id))];if(!ids.length)return Promise.resolve([] as Record<string,unknown>[]);const marginMs=Math.max(86_400_000,...providers.map(provider=>Number(provider.travelBufferMinutes)*60_000).filter(Number.isFinite)),from=new Date(Math.min(...occurrences.map(item=>Date.parse(item.start)))-marginMs).toISOString(),to=new Date(Math.max(...occurrences.map(item=>Date.parse(item.end)))+marginMs).toISOString();return chunkedIn(ids,async(chunk,placeholders)=>(await db.prepare(`SELECT ${BOOKING_READ_COLUMNS} FROM scheduling_reservations WHERE city_id=? AND status!='cancelled' AND provider_id IN (${placeholders}) AND (julianday(scheduled_start) IS NULL OR julianday(scheduled_end) IS NULL OR (julianday(scheduled_start)<julianday(?) AND (julianday(scheduled_end)>julianday(?) OR julianday(scheduled_start)>=julianday(?))))`).bind(cityId,...chunk,to,from,from).all<Record<string,unknown>>()).results);}

export function repository(db:Awaited<ReturnType<typeof database>>,input:RequestBody,options:RepositoryOptions={}):PlatformRepository{
