    const {request:input,choices}=JSON.parse(row.shortlist_json) as {request:RequestBody;choices:Array<{provider:Provider}>};
    // Use the same recurrence/calendar rules as assignment, including overnight overlaps.
    const occurrences=buildOccurrences({...input,cityId:cityIdFor(input),zoneId:zoneIdFor(input)}).filter(occ=>Date.parse(occ.start)<Date.parse(dayEnd)&&Date.parse(occ.end)>Date.parse(dayStart));
