import {
  loadFoodCatalogue,
  quoteFoodCart,
  placeQuotedFoodOrders,
  type FoodCatalogueItem,
  type FoodCartLine,
  type FoodOrderResult,
  type FoodQuote,
} from "../../lib/food-client";
