er <span>(optional)</span><textarea aria-label="Special instructions to groomer" value={specialInstructions} maxLength={500} onChange={event=>setSpecialInstructions(event.target.value)}/></label></section><div className={styles.pay}>{[["after","Pay after service","Nothing charged now; payment becomes due after completion"],["online","Pay online","Secure Razorpay sandbox checkout"]].map(p=><button key={p[0]} disabled={Boolean(sub)&&p[0]==="after"} className={pay===p[0]?styles.selected:""} onClick={()=>setPay(p[0])}><b>{p[1]}</b><span>{p[2]}</span></button>)}</div>{customer&&<CouponField cartKey={JSON.stringify([type,count,[...addons].sort()])} service="Grooming" orderValue={subtotal} customerId={customer.customerId} customerKind={sub?"subscriber":"existing"} isSubscription={Boolean(sub)} paymentMode={pay==="online"?"full":"after_service"} cityId={serviceLocation?.assignment.cityId??""} packageCode={sub?subscriptionCode(sub.id,type):catalogueCode(type,pack.id)} onDiscountChange={(value,code,quoteId)=>{setDiscount(value);setCouponCode(code);setCouponQuoteId(quoteId||"");}}/>}<article className={styles.total}>{discount>0&&<span>Coupon saving<b>−{money(discount)}</b></span>}<span>Total incl. all charges<b>{money(total)}</b></span><small>The governed coupon quote is consumed only after the canonical booking is created.</small></article><p className={styles.hint}>This UAT confirmation creates sandbox records only; it does not move live money or send production messages.</p><button className={styles.back} onClick={()=>setStep(3)}>← Slot</button>{customer&&serviceLocation&&!checkoutValidation.success&&<p className={styles.hint} role="status">To confirm: {checkoutValidation.error.issues[0]?.message||"complete the booking details above."}</p>}{customer&&serviceLocation&&livePriceState.failed&&<p className={styles.hint} role="alert">We couldn’t confirm the current price for this slot, so booking is paused rather than risk charging the wrong amount. <button className={styles.back} onClick={()=>setLiveQuoteAttempt(n=>n+1)}>Retry price check</button></p>}{customer&&serviceLocation&&checkoutValidation.success&&couponPendingReapply&&<p className={styles.hint} role="alert">Your booking details changed, so your coupon is being rechecked against the new total. Confirm unlocks as soon as the fresh quote lands.</p>}<button className={styles.primary} onClick={confirm} disabled={scheduling||!checkoutReady} aria-disabled={!checkoutReady}>{scheduling?"Reserving groomer…":"Confirm booking"}</button>{scheduleError&&<p role="alert">{scheduleError}</p>}</>}
 </section>;
}
function Head({title,note}:{title:string;note:string}){return <div className={styles.head}><h3>{title}</h3><small>{note}</small></div>;}
function Title({title,note}:{title:string;note:string}){return <div className={styles.section}><b>{title}</b><span>{note}</span></div>;}
function Info({title,children}:{title:string;children:React.ReactNode}){return <article className={styles.info}><b>{title}</b><span>{children}</span></article>;}

