 }
 async function callDriver(){if(!booking)return;setBusy(true);setError("");try{await maskedCall(booking.bookingId);setMessage("Masked call bridge requested. Your number and the driver's number remain hidden.")}catch(e){setError(taxiErrorMessage(e,"connect your call"))}finally{setBusy(false)}}
 if(!booking&&recoveryBookingId)return <BookingReferenceRecovery bookingId={recoveryBookingId} service="taxi" routeScope={routeScope} className={styles.wrap}/>;
 return <div className={styles.wrap}>
  <header className={styles.journeyIntro}><span>{sourceBookingId?"BOARDING → PET TAXI":"PAWSPACE PET TAXI"}</span><div><h2>Safe rides for pets and people.</h2><small>PawSpace and partner fleet · route and capacity checks · secure booking</small></div><b>{Math.min(visibleStage,5)}<i>/5</i></b></header>
  <div className={styles.steps}>{[1,2,3,4,5].map(n=><span key={n} className={visibleStage>=n?styles.active:""}>{n}</span>)}</div>
