const localDate=indiaDateOffset;
const toIso=(date:string,time:string)=>indiaInputInstant(`${date}T${time}`);
const petIcon=(species:string)=>species==="cat"?"🐈":species==="dog"?"🐕":"🐾";
const carImage:Record<TaxiVehicleClass,string>={citroen_ec3:"/assets/banners/taxi-car-window.jpg",xuv:"/assets/banners/taxi-vintage-truck.jpg"};

async function maskedCall(bookingId:string){return taxiRequest<{status?:string}>("/api/communications/voice/bridge",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({bookingId,idempotencyKey:`taxi-customer-call:${bookingId}:${Date.now()}`})},{action:"connect your call",refused:"Unable to start masked driver call",timeoutMs:45_000});}

export default function TaxiFlow({customer,sourceBookingId,routeScope="legacy"}:{customer:LoggedInCustomer;sourceBookingId?:string;routeScope?:"legacy"|"v2"}){
