 const[checkoutState,setCheckoutState]=useState<CheckoutState>({phase:"ready",message:"",canCheck:false});
 const[stage,setStage]=useState(1),[pets,setPets]=useState<CustomerPet[]>([]),[selectedPets,setSelectedPets]=useState<string[]>([]),[petsLoading,setPetsLoading]=useState(true),[petsFailed,setPetsFailed]=useState(false),[petsAttempt,setPetsAttempt]=useState(0),[showPetManager,setShowPetManager]=useState(false);
 const[passengers,setPassengers]=useState(1),[luggage,setLuggage]=useState(0),[tripType,setTripType]=useState<TaxiTripType>("one_way"),[waiting,setWaiting]=useState(0),[hyperactive,setHyperactive]=useState(false);
 const[pickup,setPickup]=useState(""),[drop,setDrop]=useState(""),[returnDrop,setReturnDrop]=useState(""),[date,setDate]=useState(()=>localDate(1)),[time,setTime]=useState("09:00"),[pincode,setPincode]=useState("");
 // The PIN as typed or saved is validated whole (lib/pincode-validation.ts); it is never stripped or truncated.
 const pinValid=strictServicePincode(pincode).ok;
 // Workbook Taxi row 1: every fare is calculated from the actual route kilometres; the airport flat-fare choice is gone.
 const purpose:TaxiRidePurpose="regular";
 // Workbook Taxi rows 3 and 6: the pickup address and its PIN are chosen together (a saved address fills both) and are
 // checked against the service zone here, at the trip step, with the same consistency rule the server applies at reserve.
 const[addresses,setAddresses]=useState<CustomerAccountRecord["addresses"]>([]),[savedAddressId,setSavedAddressId]=useState("");
