  if(!pinValid||pickup.trim().length<5)return;
  let active=true;const key=pickupKey;
  queueMicrotask(()=>{if(active)setPickupCheck({key,status:"checking",text:"Checking that PawSpace serves this pickup…"});});
  resolveServiceCoverage(pincode).then(coverage=>{if(!active)return;const conflict=serviceAddressConflict(pickup,coverage.city,coverage.pincode);setPickupCheck(conflict?{key,status:"error",text:conflict}:{key,status:"ok",text:`${coverage.zoneName}, ${coverage.city} · PIN ${coverage.pincode} is served.`});})
   .catch(e=>{if(active)setPickupCheck({key,status:"error",text:taxiErrorMessage(e,"check the pickup PIN")});});
  return()=>{active=false;};
 },[pickupKey,pickup,pincode,pinValid]);
 const[quotedKey,setQuotedKey]=useState("");
 const[quote,setQuote]=useState<TaxiRideQuote|null>(null),[vehicle,setVehicle]=useState<TaxiVehicleClass>("citroen_ec3"),[driver,setDriver]=useState<AssignedDriver|null>(null),[booking,setBooking]=useState<TaxiRideBookingResult|null>(null),[busy,setBusy]=useState(false),[paying,setPaying]=useState(false),[message,setMessage]=useState(""),[error,setError]=useState("");
 useFlowHistory("taxi",stage,setStage);
 useEffect(()=>{let active=true;loadCustomerAccount(customer.customerId).then(account=>{if(!active)return;const rows=account.pets;setPets(rows);setSelectedPets(rows[0]?[rows[0].id]:[]);setAddresses(account.addresses);}).catch(e=>{if(active){setPetsFailed(true);setError(taxiErrorMessage(e,"load your pets"))}}).finally(()=>active&&setPetsLoading(false));return()=>{active=false}},[customer.customerId,petsAttempt]);
 const visibleStage=booking?5:stage;
 const paymentBookingId=booking?.bookingId;
 useEffect(()=>{
  if(!paymentBookingId){checkoutController.current=null;return;}
  let active=true;
  queueMicrotask(()=>{if(active)setCheckoutState({phase:"ready",message:"",canCheck:false});});
  const controller=new CustomerCheckoutController(paymentBookingId,state=>{
   if(!active)return;
   setCheckoutState(state);
   if(state.phase==="captured") returnToBooking(paymentBookingId);
  });
  checkoutController.current=controller;
  return()=>{active=false;if(checkoutController.current===controller)checkoutController.current=null;};
 },[paymentBookingId]);
 useEffect(()=>{
  if(checkoutState.phase!=="pending")return;
  const timer=window.setInterval(()=>void checkoutController.current?.resume(),2500);
  return()=>window.clearInterval(timer);
 },[checkoutState.phase]);
 const chosenPets=useMemo(()=>pets.filter(p=>selectedPets.includes(p.id)),[pets,selectedPets]);
 const scheduledStart=toIso(date,time),addressesValid=pickup.trim().length>=5&&drop.trim().length>=5&&(tripType==="one_way"||returnDrop.trim().length>=5),countsValid=chosenPets.length>=1&&chosenPets.length<=6;
 const selection={originLabel:pickup,destinationLabel:drop,returnDropLabel:returnDrop,passengerCount:passengers,petIds:chosenPets.map(p=>p.id),luggageCount:luggage,scheduledStart,tripType,ridePurpose:purpose,waitingMinutes:waiting};
 const selectionKey=taxiSelectionKey(selection);
 const option=quote?.fareOptions[vehicle] as TaxiRideFareOption|undefined;
