 async function calculate(){if(actionLock.current)return;actionLock.current=true;const pricedKey=selectionKey;setBusy(true);setError("");try{requireFutureIndiaInput(`${date}T${time}`);const q=await createTaxiRideQuote({originLabel:pickup.trim(),destinationLabel:drop.trim(),returnDropLabel:tripType==="round_trip"?returnDrop.trim():undefined,passengerCount:passengers,petCount:chosenPets.length,luggageCount:luggage,scheduledStart,tripType,ridePurpose:purpose,waitingMinutes:tripType==="round_trip"?waiting:0});setQuote(q);setQuotedKey(pricedKey);setVehicle(q.recommendedVehicleClass);setStage(4)}catch(e){setError(taxiErrorMessage(e,"calculate your Pet Taxi fare"))}finally{actionLock.current=false;setBusy(false)}}
 async function reserve(){if(actionLock.current||!quote||!option?.eligible)return;if(quotedKey!==selectionKey||!taxiQuoteMatchesSelection(quote,selection)){setQuote(null);setStage(3);setError("Your ride details changed or the quote expired. Recalculate the fare before reserving.");return;}actionLock.current=true;setBusy(true);setError("");try{const coverage=await resolveServiceCoverage(pincode);const requestId=`taxi-v2-${customer.customerId}-${quote.quoteId}-${vehicle}`;const reservation=await reserveTaxiSchedule({clientRequestId:requestId,customerId:customer.customerId,petIds:chosenPets.map(p=>p.id),cityId:coverage.cityId,zoneId:coverage.zoneId,scheduledStart:quote.scheduledStart,scheduledEnd:quote.scheduledEnd,serviceAddress:pickup.trim(),servicePincode:pincode.trim(),vehicleClass:vehicle});const created=await createCanonicalTaxiRideBooking({idempotencyKey:requestId,groupId:reservation.groupId,taxiQuoteId:quote.quoteId,vehicleClass:vehicle,customer:{id:customer.customerId,name:customer.customerName,primaryPhone:customer.phone},pets:chosenPets.map(p=>({sourceId:p.sourceId??p.id,name:p.name,species:p.species==="cat"?"cat":p.species==="dog"?"dog":"other",breed:p.breed??undefined,vaccinationStatus:p.vaccinationStatus})),cityId:coverage.cityId,zoneId:coverage.zoneId,scheduledStart:quote.scheduledStart,scheduledEnd:quote.scheduledEnd,provider:reservation.driver,totalAmount:Number(option.quotedTotal),amountDueNow:Number(option.bookingFee),hyperactivePet:hyperactive,channel:sourceBookingId?"boarding_cross_sell":"customer_app",sourceBookingId:sourceBookingId||undefined});setDriver(reservation.driver);setBooking(created);rememberBookingReference(created.bookingId);setStage(5);setMessage("Vehicle and driver held for 3 hours. Pay the 50% booking fee to confirm the ride.")}catch(e){setError(taxiErrorMessage(e,"reserve your Pet Taxi"))}finally{actionLock.current=false;setBusy(false)}}
