export type FoodCatalogueItem={sku:string;name:string;pet_type:"dog"|"cat";pack_size:string;unit_price:number;currency:string;max_qty_per_order:number;version:number;uat_available_units:number;inventory_mode:"uat_seed";production_inventory_verified:false};
export type FoodQuote={quoteId:string;sku:string;name:string;version:number;petType:"dog"|"cat";petIds:string[];packSize:string;quantity:number;unitPrice:number;deliveryFee:0;totalAmount:number;amountDueNow:0;currency:"INR";zoneId:string;paymentMode:"sandbox_deferred";expiresAt:number;inventoryMode:"uat_seed";productionInventoryVerified:false;liveMoney:false};
export type FoodOrderResult={orderId:string;status:string;petIds:string[];lineId:string;reservationId:string;paymentId:string;totalAmount:number;amountDueNow:0;inventoryMode:"uat_seed";productionInventoryVerified:false;deliveryStatus:string;liveMoney:false;duplicatePrevented:boolean};
export async function loadFoodCatalogue(zoneId="blr-east"){const response=await fetch(`/api/food-commercial?zoneId=${encodeURIComponent(zoneId)}`,{cache:"no-store"});const body=await response.json();if(!response.ok)throw new Error(body.error||"Unable to load Food catalogue");return body.data as {items:FoodCatalogueItem[];source:string;inventoryMode:string;productionInventoryVerified:false;deliveryFeePolicy:string;liveMoney:false}}
