 db.prepare("CREATE TABLE IF NOT EXISTS food_order_fulfilment (order_id TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'reserved',lot_id TEXT,dispatch_reference TEXT,delivery_adapter_status TEXT NOT NULL DEFAULT 'not_connected',handover_status TEXT NOT NULL DEFAULT 'pending',updated_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS food_fulfilment_events (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,event_type TEXT NOT NULL,actor_id TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL)"),
