 db.prepare("CREATE TABLE IF NOT EXISTS food_delivery_handover_events (order_id TEXT PRIMARY KEY,method TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'uat_confirmed',otp_status TEXT NOT NULL DEFAULT 'not_connected',confirmed_by TEXT NOT NULL,confirmed_at INTEGER NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS food_stock_recovery_cases (id TEXT PRIMARY KEY,order_id TEXT NOT NULL,sku TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ops_review_required',substitution_allowed INTEGER NOT NULL DEFAULT 0,opened_by TEXT NOT NULL,opened_at INTEGER NOT NULL,resolved_at INTEGER,updated_at INTEGER NOT NULL)"),
