}return{processed:results.length,results,skippedForCity,automaticEngine:"scheduler_ready",schedulerConnected:false,autoCharge:false,liveMoney:false};}

async function queuePaidMessages(db:D1Database,sub:Row,renewal:Row,invoice:Row,actorId:string){const confirmation=await enqueueCommunication(db,{customerId:String(sub.customer_id),cityId:String(sub.city_id),channel:String(sub.communication_channel) as FoodSubscriptionChannel,purpose:"transactional",idempotencyKey:`food-subscription-paid:${renewal.id}`,templateKey:"food_subscription_renewal_paid",payload:{subscriptionId:sub.id,renewalId:renewal.id,invoiceId:invoice.id,invoiceNumber:invoice.invoice_number,itemName:sub.item_name,amount:Number(renewal.total_amount),currency:"INR",nextRenewalAt:Number(sub.next_renewal_at),paymentConfirmed:true,liveMoney:false},createdBy:actorId,bookingId:String(sub.source_order_id)}),customer=await db.prepare("SELECT email FROM canonical_customers WHERE id=?").bind(sub.customer_id).first<Row>(),invoiceChannel=String(customer?.email||"").includes("@")?"email":String(sub.communication_channel) as FoodSubscriptionChannel,invoiceMessage=await enqueueCommunication(db,{customerId:String(sub.customer_id),cityId:String(sub.city_id),channel:invoiceChannel as FoodSubscriptionChannel,purpose:"transactional",idempotencyKey:`food-subscription-invoice:${renewal.id}`,templateKey:"food_subscription_renewal_invoice",payload:{subscriptionId:sub.id,renewalId:renewal.id,invoiceId:invoice.id,invoiceNumber:invoice.invoice_number,invoicePath:`/food/subscription-invoice?invoiceId=${encodeURIComponent(String(invoice.id))}`,grossAmount:Number(invoice.gross_amount),taxAmount:Number(invoice.tax_amount),netAmount:Number(invoice.net_amount),currency:"INR",taxRuleStatus:invoice.tax_rule_status,invoiceKind:invoice.invoice_kind,productionTaxInvoice:false},createdBy:actorId,bookingId:String(sub.source_order_id)}),confirmationId=String((confirmation as Record<string,unknown>).messageId||((confirmation as Record<string,unknown>).message as Row|undefined)?.id||""),invoiceMessageId=String((invoiceMessage as Record<string,unknown>).messageId||((invoiceMessage as Record<string,unknown>).message as Row|undefined)?.id||"");await db.prepare("UPDATE food_subscription_renewals SET confirmation_message_id=COALESCE(confirmation_message_id,?),invoice_message_id=COALESCE(invoice_message_id,?),updated_at=? WHERE id=?").bind(confirmationId||null,invoiceMessageId||null,Date.now(),renewal.id).run();return{confirmation,invoiceMessage};}

export async function recordFoodSubscriptionRenewalPayment(db:D1Database,input:{renewalId:string;paymentReference:string;actorId:string}){
 await ensureFoodSubscriptionTables(db);
 let renewal=await db.prepare("SELECT * FROM food_subscription_renewals WHERE id=?").bind(input.renewalId).first<Row>();if(!renewal)throw new Response("Food subscription renewal not found",{status:404});
 const sub=await subscriptionById(db,String(renewal.subscription_id));if(!sub)throw new Response("Food subscription not found",{status:404});
 const reference=String(input.paymentReference||"").trim();if(reference.length<5)throw new Response("Canonical Food renewal payment reference is required",{status:400});
 const used=await db.prepare("SELECT id FROM food_subscription_renewals WHERE payment_reference=? AND id<>?").bind(reference,renewal.id).first<Row>();if(used)throw new Response("Food renewal payment reference was already used",{status:409});
 if(String(renewal.payment_reference||"")&&String(renewal.payment_reference)!==reference)throw new Response("Food renewal is already paid with a different canonical reference",{status:409});
 let duplicatePayment=String(renewal.status)==="paid_invoiced";
 let invoice=await db.prepare("SELECT * FROM food_subscription_invoices WHERE renewal_id=?").bind(renewal.id).first<Row>();
 let deliveryOrderId=String(renewal.delivery_order_id||"");
 if(!duplicatePayment){
  if(!["payment_pending","payment_confirmed_order_pending"].includes(String(renewal.status)))throw new Response("Food subscription renewal is not awaiting payment",{status:409});
  const now=Date.now();
  if(String(renewal.status)==="payment_pending"){await db.prepare("UPDATE food_subscription_renewals SET status='payment_confirmed_order_pending',payment_reference=?,paid_at=?,updated_at=? WHERE id=? AND status='payment_pending'").bind(reference,now,now,renewal.id).run();renewal={...renewal,status:"payment_confirmed_order_pending",payment_reference:reference,paid_at:now};}
  let quoteId=String(renewal.delivery_quote_id||"");
  if(!quoteId){const petIds=await foodSubscriptionPetIds(db,String(sub.id));if(!petIds.length)throw new Response("Food subscription is missing canonical pet lineage for renewal order",{status:409});const quote=await createFoodQuote(db,{sku:String(sub.sku),quantity:Number(sub.quantity),zoneId:String(sub.zone_id),paymentMode:"sandbox_deferred",customerId:String(sub.customer_id),petIds});quoteId=quote.quoteId;await db.prepare("UPDATE food_subscription_renewals SET delivery_quote_id=?,updated_at=? WHERE id=?").bind(quoteId,Date.now(),renewal.id).run();}
  const orderResult=await createFoodOrder(db,{idempotencyKey:`food-renewal-order:${String(renewal.id)}`,quoteId,customerId:String(sub.customer_id),cityId:String(sub.city_id),zoneId:String(sub.zone_id),actorId:input.actorId,prepaid:{reference,source:"food_subscription_renewal"}});
  deliveryOrderId=String(orderResult.orderId);await db.prepare("UPDATE food_subscription_renewals SET delivery_order_id=?,updated_at=? WHERE id=?").bind(deliveryOrderId,Date.now(),renewal.id).run();
  const invoiceId=`FINV-${crypto.randomUUID().slice(0,12).toUpperCase()}`,invoiceNumber=`PS-FS-${new Date(now).getUTCFullYear()}-${crypto.randomUUID().slice(0,8).toUpperCase()}`,nextRenewalAt=Number(sub.next_renewal_at)+Number(sub.renewal_interval_days)*DAY,policy=await resolveFoodCommercialPolicy(db,String(sub.city_id||"blr")),tax=foodTaxFromGross(Number(renewal.total_amount),policy.config);
  await db.batch([db.prepare("UPDATE food_subscription_renewals SET status='paid_invoiced',invoice_id=?,delivery_order_id=?,updated_at=? WHERE id=? AND status='payment_confirmed_order_pending'").bind(invoiceId,deliveryOrderId,now,renewal.id),db.prepare("INSERT INTO food_subscription_invoices (id,subscription_id,renewal_id,customer_id,invoice_number,status,currency,gross_amount,tax_amount,net_amount,tax_rule_status,invoice_kind,issued_at,created_at,updated_at) VALUES (?,?,?,?,?,'issued','INR',?,?,?,?, 'uat_renewal_invoice',?,?,?)").bind(invoiceId,sub.id,renewal.id,sub.customer_id,invoiceNumber,Number(renewal.total_amount),tax.taxAmount,tax.netAmount,tax.taxStatus,now,now,now),db.prepare("UPDATE food_subscriptions SET current_cycle=?,next_renewal_at=?,updated_at=? WHERE id=?").bind(Number(renewal.cycle_no),nextRenewalAt,now,sub.id)]);
  await addEvent(db,{subscriptionId:String(sub.id),renewalId:String(renewal.id),eventType:"renewal_payment_confirmed",idempotencyKey:`food-subscription:${renewal.id}:paid`,actorId:input.actorId,detail:{paymentReference:reference,amount:Number(renewal.total_amount),invoiceId,invoiceNumber,nextRenewalAt,deliveryOrderId,autoCharge:false,productionTaxInvoice:false,deliveryOrderGeneration:"canonical_reserved_prepaid"}});
  invoice=await db.prepare("SELECT * FROM food_subscription_invoices WHERE id=?").bind(invoiceId).first<Row>();duplicatePayment=false;
 }
 const currentRenewal=await db.prepare("SELECT * FROM food_subscription_renewals WHERE id=?").bind(renewal.id).first<Row>(),currentSub=await subscriptionById(db,String(sub.id));if(!invoice||!currentRenewal||!currentSub)throw new Response("Food renewal payment ledger is incomplete",{status:500});
 await queuePaidMessages(db,currentSub,currentRenewal,invoice,input.actorId);
 return{subscriptionId:sub.id,renewalId:renewal.id,status:"paid_invoiced",paymentReference:String(currentRenewal.payment_reference||reference),invoiceId:invoice.id,invoiceNumber:invoice.invoice_number,amount:Number(currentRenewal.total_amount),nextRenewalAt:Number(currentSub.next_renewal_at),deliveryOrderId:String(currentRenewal.delivery_order_id||deliveryOrderId),confirmationQueued:true,invoiceQueued:true,duplicatePayment,autoCharge:false,liveMoney:false,productionTaxInvoice:false,deliveryOrderGeneration:"canonical_reserved_prepaid"};
}

export async function getFoodSubscriptionSnapshot(db:D1Database,input:{subscriptionId?:string;renewalId?:string;invoiceId?:string}){await ensureFoodSubscriptionTables(db);let subscriptionId=String(input.subscriptionId||"");if(!subscriptionId&&input.renewalId){const row=await db.prepare("SELECT subscription_id FROM food_subscription_renewals WHERE id=?").bind(input.renewalId).first<Row>();subscriptionId=String(row?.subscription_id||"")}if(!subscriptionId&&input.invoiceId){const row=await db.prepare("SELECT subscription_id FROM food_subscription_invoices WHERE id=?").bind(input.invoiceId).first<Row>();subscriptionId=String(row?.subscription_id||"")}if(!subscriptionId)return null;const subscription=await subscriptionById(db,subscriptionId);if(!subscription)return null;const[renewals,invoices,events]=await Promise.all([db.prepare("SELECT * FROM food_subscription_renewals WHERE subscription_id=? ORDER BY cycle_no DESC LIMIT 50").bind(subscriptionId).all<Row>(),db.prepare("SELECT * FROM food_subscription_invoices WHERE subscription_id=? ORDER BY issued_at DESC LIMIT 50").bind(subscriptionId).all<Row>(),db.prepare("SELECT * FROM food_subscription_events WHERE subscription_id=? ORDER BY created_at DESC LIMIT 100").bind(subscriptionId).all<Row>()]);return{subscription,renewals:renewals.results,invoices:invoices.results,events:events.results.map(row=>({...row,detail:parse(row.detail_json,{})})),truth:{automaticRenewalEngine:"scheduler_ready",schedulerConnected:false,renewalMethod:"payment_link",autoCharge:false,liveMoney:false,silentRepricing:false,productionTaxInvoice:false,taxRuleStatus:"configuration_required",deliveryOrderGeneration:"canonical_reserved_prepaid"}};}

