import{enqueueCommunication,type CommunicationChannel}from"./communication-engine";
import{createFoodOrder,createFoodQuote,ensureFoodGovernanceTables}from"./food-governance";
import{foodSubscriptionPetIds}from"./food-pet-association";
import{foodTaxFromGross,resolveFoodCommercialPolicy}from"./food-commercial-policy";

type Row=Record<string,unknown>;
export type FoodSubscriptionChannel=Extract<CommunicationChannel,"whatsapp"|"sms"|"email"|"push">;
export type FoodSubscriptionStatus="active"|"paused"|"cancelled";
export type FoodSubscriptionCreateInput={sourceOrderId:string;customerId:string;renewalIntervalDays:number;communicationChannel?:FoodSubscriptionChannel;firstRenewalAt?:number;actorId:string};

const DAY=86_400_000;
const parse=<T>(value:unknown,fallback:T):T=>{try{return JSON.parse(String(value??"")) as T}catch{return fallback}};
const money=(value:unknown)=>Number(Number(value||0).toFixed(2));

export async function ensureFoodSubscriptionTables(db:D1Database){await ensureFoodGovernanceTables(db);await db.batch([
 db.prepare("CREATE TABLE IF NOT EXISTS food_subscriptions (id TEXT PRIMARY KEY,source_order_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,city_id TEXT NOT NULL,zone_id TEXT NOT NULL,sku TEXT NOT NULL,item_name TEXT NOT NULL,quantity INTEGER NOT NULL,renewal_interval_days INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'active',communication_channel TEXT NOT NULL DEFAULT 'whatsapp',unit_price_at_signup REAL NOT NULL,approved_unit_price REAL NOT NULL,current_cycle INTEGER NOT NULL DEFAULT 0,next_renewal_at INTEGER NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)"),
 db.prepare("CREATE INDEX IF NOT EXISTS idx_food_subscriptions_due ON food_subscriptions(status,next_renewal_at)"),
 db.prepare("CREATE TABLE IF NOT EXISTS food_subscription_renewals (id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL,cycle_no INTEGER NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL,item_version INTEGER NOT NULL,unit_price REAL NOT NULL,total_amount REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'INR',status TEXT NOT NULL DEFAULT 'payment_pending',payment_link_provider TEXT NOT NULL DEFAULT 'internal_uat',payment_link_environment TEXT NOT NULL DEFAULT 'uat',payment_link_ref TEXT NOT NULL UNIQUE,payment_link_path TEXT NOT NULL,payment_link_message_id TEXT,payment_reference TEXT UNIQUE,invoice_id TEXT,confirmation_message_id TEXT,invoice_message_id TEXT,delivery_quote_id TEXT,delivery_order_id TEXT UNIQUE,due_at INTEGER NOT NULL,paid_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(subscription_id,cycle_no))"),
 db.prepare("CREATE INDEX IF NOT EXISTS idx_food_subscription_renewals_status ON food_subscription_renewals(status,due_at)"),
 db.prepare("CREATE TABLE IF NOT EXISTS food_subscription_invoices (id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL,renewal_id TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL,invoice_number TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'issued',currency TEXT NOT NULL DEFAULT 'INR',gross_amount REAL NOT NULL,tax_amount REAL NOT NULL DEFAULT 0,net_amount REAL NOT NULL,tax_rule_status TEXT NOT NULL DEFAULT 'configuration_required',invoice_kind TEXT NOT NULL DEFAULT 'uat_renewal_invoice',issued_at INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL)"),
 db.prepare("CREATE TABLE IF NOT EXISTS food_subscription_events (id TEXT PRIMARY KEY,subscription_id TEXT NOT NULL,renewal_id TEXT,event_type TEXT NOT NULL,idempotency_key TEXT NOT NULL UNIQUE,actor_id TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL)"),
]);for(const ddl of["ALTER TABLE food_subscription_renewals ADD COLUMN delivery_quote_id TEXT","ALTER TABLE food_subscription_renewals ADD COLUMN delivery_order_id TEXT"]){try{await db.prepare(ddl).run()}catch(error){if(!/duplicate column|already exists/i.test(error instanceof Error?error.message:String(error)))throw error}}await db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS idx_food_subscription_delivery_order ON food_subscription_renewals(delivery_order_id) WHERE delivery_order_id IS NOT NULL").run()}

async function addEvent(db:D1Database,input:{subscriptionId:string;renewalId?:string;eventType:string;idempotencyKey:string;actorId:string;detail?:Record<string,unknown>}){await db.prepare("INSERT OR IGNORE INTO food_subscription_events (id,subscription_id,renewal_id,event_type,idempotency_key,actor_id,detail_json,created_at) VALUES (?,?,?,?,?,?,?,?)").bind(crypto.randomUUID(),input.subscriptionId,input.renewalId??null,input.eventType,input.idempotencyKey,input.actorId,JSON.stringify(input.detail??{}),Date.now()).run();}

async function subscriptionById(db:D1Database,id:string){await ensureFoodSubscriptionTables(db);return db.prepare("SELECT * FROM food_subscriptions WHERE id=?").bind(id).first<Row>();}

export async function createFoodSubscription(db:D1Database,input:FoodSubscriptionCreateInput){await ensureFoodSubscriptionTables(db);if(!input.sourceOrderId||!input.customerId||!input.actorId)throw new Response("Source order, customer and actor are required",{status:400});const interval=Math.floor(Number(input.renewalIntervalDays));if(!Number.isFinite(interval)||interval<7||interval>90)throw new Response("Food renewal interval must be an explicit customer-selected 7-90 days",{status:400});const channel=input.communicationChannel??"whatsapp";if(!["whatsapp","sms","email","push"].includes(channel))throw new Response("Unsupported Food subscription communication channel",{status:400});const prior=await db.prepare("SELECT * FROM food_subscriptions WHERE source_order_id=?").bind(input.sourceOrderId).first<Row>();if(prior)return{subscriptionId:String(prior.id),status:String(prior.status),nextRenewalAt:Number(prior.next_renewal_at),duplicatePrevented:true,autoCharge:false};const source=await db.prepare("SELECT o.id,o.customer_id,o.city_id,o.zone_id,o.status,l.sku,l.item_name,l.quantity,l.unit_price FROM food_orders o JOIN food_order_lines l ON l.order_id=o.id WHERE o.id=?").bind(input.sourceOrderId).first<Row>();if(!source)throw new Response("Canonical Food source order not found",{status:404});if(String(source.customer_id)!==input.customerId)throw new Response("Food source order and subscription customer do not match",{status:403});if(String(source.status)==="cancelled")throw new Response("Cancelled Food order cannot start a subscription",{status:409});const now=Date.now(),first=input.firstRenewalAt==null?now+interval*DAY:Number(input.firstRenewalAt);if(!Number.isFinite(first)||first<=now)throw new Response("First Food renewal must be scheduled in the future",{status:400});const id=`FSUB-${crypto.randomUUID().slice(0,12).toUpperCase()}`,unitPrice=money(source.unit_price);await db.prepare("INSERT INTO food_subscriptions (id,source_order_id,customer_id,city_id,zone_id,sku,item_name,quantity,renewal_interval_days,status,communication_channel,unit_price_at_signup,approved_unit_price,current_cycle,next_renewal_at,created_by,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,'active',?,?,?,0,?,?,?,?)").bind(id,source.id,source.customer_id,source.city_id,source.zone_id,source.sku,source.item_name,Number(source.quantity),interval,channel,unitPrice,unitPrice,first,input.actorId,now,now).run();await addEvent(db,{subscriptionId:id,eventType:"subscription_created",idempotencyKey:`food-subscription:create:${input.sourceOrderId}`,actorId:input.actorId,detail:{sourceOrderId:source.id,renewalIntervalDays:interval,communicationChannel:channel,nextRenewalAt:first,autoCharge:false,liveMoney:false}});return{subscriptionId:id,status:"active",nextRenewalAt:first,renewalIntervalDays:interval,communicationChannel:channel,autoCharge:false,liveMoney:false,duplicatePrevented:false};}

export async function setFoodSubscriptionStatus(db:D1Database,input:{subscriptionId:string;status:FoodSubscriptionStatus;actorId:string;reason:string}){await ensureFoodSubscriptionTables(db);const sub=await subscriptionById(db,input.subscriptionId);if(!sub)throw new Response("Food subscription not found",{status:404});const reason=String(input.reason||"").trim();if(reason.length<3)throw new Response("A Food subscription status-change reason is required",{status:400});if(String(sub.status)==="cancelled"&&input.status!=="cancelled")throw new Response("Cancelled Food subscription cannot be reactivated",{status:409});const now=Date.now();await db.prepare("UPDATE food_subscriptions SET status=?,updated_at=? WHERE id=?").bind(input.status,now,input.subscriptionId).run();await addEvent(db,{subscriptionId:input.subscriptionId,eventType:`subscription_${input.status}`,idempotencyKey:`food-subscription:${input.subscriptionId}:${input.status}:${now}`,actorId:input.actorId,detail:{reason}});return getFoodSubscriptionSnapshot(db,{subscriptionId:input.subscriptionId});}

async function queuePaymentLinkMessage(db:D1Database,sub:Row,renewal:Row,actorId:string){const result=await enqueueCommunication(db,{customerId:String(sub.customer_id),cityId:String(sub.city_id),channel:String(sub.communication_channel) as FoodSubscriptionChannel,purpose:"transactional",idempotencyKey:`food-subscription-renewal-link:${renewal.id}`,templateKey:"food_subscription_renewal_payment_link",payload:{subscriptionId:sub.id,renewalId:renewal.id,itemName:sub.item_name,sku:sub.sku,quantity:Number(sub.quantity),amount:Number(renewal.total_amount),currency:"INR",paymentLinkPath:renewal.payment_link_path,dueAt:Number(renewal.due_at),autoCharge:false,liveMoney:false,paymentLinkEnvironment:"uat"},createdBy:actorId,bookingId:String(sub.source_order_id)}),messageId=String((result as Record<string,unknown>).messageId||((result as Record<string,unknown>).message as Row|undefined)?.id||"");if(messageId)await db.prepare("UPDATE food_subscription_renewals SET payment_link_message_id=COALESCE(payment_link_message_id,?),updated_at=? WHERE id=?").bind(messageId,Date.now(),renewal.id).run();return result;}

/*
 * A paused city does not renew customers into itself. [PTJA-W1-F38]
 *
 * The approved matrix names automatic subscription renewal scheduling as one of the things a pause must
 * stop, alongside new bookings, manual bookings and wait-list conversion - and it is the easiest of the
 * four to miss, because nobody is watching when a scheduled sweep quietly books work into a closed
 * market. Existing renewals already created are untouched: a pause stops NEW work and never reaches back.
 */
async function cityAcceptsRenewal(db:D1Database,sub:Row){
  const{cityBookingVerdict}=await import("./city-status-authority");
  const verdict=await cityBookingVerdict(db,{cityId:String(sub.city_id||""),serviceCode:"food",channel:"subscription_renewal"}).catch(()=>null);
  return verdict?verdict.allowed:true;
}

async function createOrLoadRenewal(db:D1Database,sub:Row,actorId:string,at:number){const cycleNo=Number(sub.current_cycle||0)+1,existing=await db.prepare("SELECT * FROM food_subscription_renewals WHERE subscription_id=? AND cycle_no=?").bind(sub.id,cycleNo).first<Row>();if(existing){if(String(existing.status)==="payment_pending")await queuePaymentLinkMessage(db,sub,existing,actorId);return{subscriptionId:sub.id,renewalId:existing.id,status:existing.status,cycleNo,duplicatePrevented:true,paymentLinkPath:existing.payment_link_path}}if(String(sub.status)!=="active")return{subscriptionId:sub.id,status:sub.status,skipped:true};if(Number(sub.next_renewal_at)>at)return{subscriptionId:sub.id,status:"not_due",nextRenewalAt:Number(sub.next_renewal_at),skipped:true};const item=await db.prepare("SELECT c.*,i.available_units,i.reserved_units FROM food_catalogue_items c LEFT JOIN food_inventory_uat i ON i.sku=c.sku AND i.zone_id=? WHERE c.sku=? AND c.active=1").bind(sub.zone_id,sub.sku).first<Row>();if(!item){await addEvent(db,{subscriptionId:String(sub.id),eventType:"renewal_blocked",idempotencyKey:`food-subscription:${sub.id}:cycle:${cycleNo}:catalogue`,actorId,detail:{reason:"catalogue_item_unavailable"}});return{subscriptionId:sub.id,status:"catalogue_review_required",skipped:true}}const approved=money(sub.approved_unit_price),current=money(item.unit_price);if(Math.abs(current-approved)>0.009){await addEvent(db,{subscriptionId:String(sub.id),eventType:"renewal_price_review_required",idempotencyKey:`food-subscription:${sub.id}:cycle:${cycleNo}:price`,actorId,detail:{approvedUnitPrice:approved,currentUnitPrice:current,silentRepricing:false}});return{subscriptionId:sub.id,status:"price_review_required",approvedUnitPrice:approved,currentUnitPrice:current,silentRepricing:false,skipped:true}}const available=Math.max(0,Number(item.available_units||0)-Number(item.reserved_units||0));if(available<Number(sub.quantity)){await addEvent(db,{subscriptionId:String(sub.id),eventType:"renewal_inventory_review_required",idempotencyKey:`food-subscription:${sub.id}:cycle:${cycleNo}:inventory`,actorId,detail:{available,required:Number(sub.quantity),paymentCollected:false}});return{subscriptionId:sub.id,status:"inventory_review_required",available,required:Number(sub.quantity),paymentCollected:false,skipped:true}}const now=Date.now(),renewalId=`FREN-${crypto.randomUUID().slice(0,12).toUpperCase()}`,linkRef=`FPL-${crypto.randomUUID().slice(0,14).toUpperCase()}`,total=money(approved*Number(sub.quantity)),path=`/food/subscription-payment?renewalId=${encodeURIComponent(renewalId)}&ref=${encodeURIComponent(linkRef)}`;await db.prepare("INSERT INTO food_subscription_renewals (id,subscription_id,cycle_no,sku,quantity,item_version,unit_price,total_amount,currency,status,payment_link_provider,payment_link_environment,payment_link_ref,payment_link_path,due_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,'INR','payment_pending','internal_uat','uat',?,?,?, ?,?)").bind(renewalId,sub.id,cycleNo,sub.sku,Number(sub.quantity),Number(item.version),approved,total,linkRef,path,Number(sub.next_renewal_at),now,now).run();await addEvent(db,{subscriptionId:String(sub.id),renewalId,eventType:"renewal_payment_link_created",idempotencyKey:`food-subscription:${sub.id}:cycle:${cycleNo}:link`,actorId,detail:{amount:total,currency:"INR",paymentLinkRef:linkRef,paymentLinkPath:path,paymentLinkProvider:"internal_uat",externalPaymentExecution:false,autoCharge:false}});const renewal=await db.prepare("SELECT * FROM food_subscription_renewals WHERE id=?").bind(renewalId).first<Row>();if(renewal)await queuePaymentLinkMessage(db,sub,renewal,actorId);return{subscriptionId:sub.id,renewalId,cycleNo,status:"payment_pending",amount:total,currency:"INR",paymentLinkPath:path,paymentLinkProvider:"internal_uat",externalPaymentExecution:false,autoCharge:false,duplicatePrevented:false};}

export async function processDueFoodSubscriptionRenewals(db:D1Database,input:{actorId:string;subscriptionId?:string;at?:number}){await ensureFoodSubscriptionTables(db);const at=input.at??Date.now();let rows:Row[]=[];if(input.subscriptionId){const row=await subscriptionById(db,input.subscriptionId);if(!row)throw new Response("Food subscription not found",{status:404});rows=[row]}else rows=(await db.prepare("SELECT * FROM food_subscriptions WHERE status='active' AND next_renewal_at<=? ORDER BY next_renewal_at LIMIT 100").bind(at).all<Row>()).results;const results=[],skippedForCity=[];for(const sub of rows){
  // A paused, draft or closed city does not renew customers into itself. Skipped, not failed: the
  // subscription is untouched and will renew when the market reopens. [PTJA-W1-F38]
  if(!await cityAcceptsRenewal(db,sub)){skippedForCity.push(String(sub.id));continue;}
